const source=$input.first()?.json;
if(!source||!Array.isArray(source.workflow_runs))throw Error('MESH_INVALID_RESPONSE');
const repo='2strongtrainers-art/Nicholas-AI-OS';
const allowed={'market-desk-research.yml':'market','render-trivalley-reel.yml':'video','deploy-argus-private-forensics.yml':'argus'};
const terminal=new Set(['success','failure','skipped','cancelled','timed_out','action_required','neutral','stale','startup_failure']);
const results=new Map();
for(const r of source.workflow_runs.slice(0,50)){
  if(!r||r.head_branch!=='main'||(r.repository?.full_name&&r.repository.full_name!==repo))continue;
  if(!['workflow_dispatch','schedule'].includes(r.event))continue;
  if(typeof r.path!=='string'||!r.path.startsWith('.github/workflows/'))continue;
  const file=r.path.slice('.github/workflows/'.length);
  if(!Object.prototype.hasOwnProperty.call(allowed,file))continue;
  if(!Number.isSafeInteger(r.id)||r.id<1||!Number.isSafeInteger(r.run_attempt)||r.run_attempt<1)continue;
  if(!['completed','queued','in_progress','waiting','pending','requested'].includes(r.status))continue;
  if(r.status==='completed'&&!terminal.has(r.conclusion))continue;
  const state=r.status!=='completed'?'PENDING':r.conclusion==='success'?'UNVERIFIED':r.conclusion==='skipped'?'SKIPPED':
    ['cancelled','action_required','neutral','stale'].includes(r.conclusion)?'BLOCKED':'FAILED';
  const key=repo+':'+file+':'+r.id+':'+r.run_attempt;
  results.set(key,{json:{
    receipt_key:key,kind:allowed[file],status:state,
    evidence_level:'github_run_metadata_only',
    reason_code:state==='UNVERIFIED'?'ARTIFACT_QA_REQUIRED':state==='SKIPPED'?'INNER_JOB_SKIPPED':state==='PENDING'?'NOT_COMPLETED':state==='FAILED'?'JOB_FAILED':'JOB_BLOCKED',
    run_url:'https://github.com/'+repo+'/actions/runs/'+r.id+'/attempts/'+r.run_attempt,
    run_id:String(r.id),run_attempt:String(r.run_attempt),
    observed_at:/^\d{4}-\d{2}-\d{2}T/.test(String(r.updated_at||''))?r.updated_at:''
  }});
}
return [...results.values()].sort((a,b)=>Number(b.json.run_id)-Number(a.json.run_id)||Number(b.json.run_attempt)-Number(a.json.run_attempt));
